val_losses = [0.90, 0.70, 0.62, 0.60, 0.61, 0.63, 0.59, 0.64]
best, best_epoch, patience, waited = float("inf"), -1, 2, 0
for epoch, loss in enumerate(val_losses):
    if loss < best:
        best, best_epoch, waited = loss, epoch, 0
    else:
        waited += 1
        if waited >= patience:
            print("stop at", epoch)
            break
print("best", best_epoch, best)
